// The token generator (docs/design-system.md §2.8, §9 rulings 104 and 106): renders every committed copy of the token
// source. Each target is a pure function of the file's current text, so `--check` and tests/design-tokens.test.ts
// can compare bytes without writing. Whole generated files carry a header; copies inside a hand-written file sit
// between `tokens:begin` / `tokens:end` markers, or replace exactly one literal (JSON, a single-line HTML constant,
// a data URI) where a comment cannot go.
import {
	DEFAULT_THEME_ID,
	EXTENSION_HOST,
	HELM_TOKENS,
	HIGH_CONTRAST_TOKENS,
	POPUP_ROOT,
	PRESET_EARLIER_VALUES,
	REMOTE_OFFLINE_ROOT,
	REVIEW_LIGHT_TOKENS,
	ROOT_GROUPS,
	SCRIPT_EASINGS,
	SCRIPT_MOTION_MS,
	STORYBOOK_BACKGROUNDS,
	THEME_PRESETS,
	THEME_TOKEN_NAMES,
	rootToken,
} from './index.ts'

export const GENERATOR = 'npm run tokens:write'
export const SOURCE = 'packages/helm-ui/tokens'
const NOTICE = `generated by ${GENERATOR} from ${SOURCE}; edit the source, never this`
export const BEGIN = `/* tokens:begin (${NOTICE}) */`
export const END = '/* tokens:end */'

export interface Target {
	/** Repository-relative path. */
	file: string
	/** The file's full text given its current text (`null` when it does not exist yet). */
	render: (current: string | null) => string
}

const declarations = (tokens: Readonly<Record<string, string>>, indent: string) =>
	Object.entries(tokens).map(([name, value]) => `${indent}${name}: ${value};`)

/** The whole of `app/src/renderer/tokens.css`. */
export function tokensCss(): string {
	const lines = [
		`/* Helm design tokens on :root, ${NOTICE} (docs/design-system.md §2).`,
		' * Components consume var(--token), never literals (§2.8). The theme colours are the Helm preset for the pre-JS',
		' * first paint: appearance.ts re-applies the active theme over them at startup and on every change. */',
		':root {',
		'\tcolor-scheme: dark;',
	]
	for (const group of ROOT_GROUPS) lines.push(`\t/* ${group.comment} */`, ...declarations(group.tokens, '\t'))
	lines.push('}', '')
	return lines.join('\n')
}

// TypeScript literals in the repository's Biome style (single quotes, bare keys), so the generated modules pass
// `biome check` unchanged.
const str = (value: string) => `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`
const key = (name: string) => (/^[A-Za-z_$][\w$]*$/.test(name) ? name : str(name))
const literal = (value: string | number) => (typeof value === 'number' ? String(value) : str(value))
const objectLiteral = (record: Readonly<Record<string, string | number>>, indent: string) =>
	[
		'{',
		...Object.entries(record).map(([name, value]) => `${indent}\t${key(name)}: ${literal(value)},`),
		`${indent}}`,
	].join('\n')
const arrayLiteral = (values: readonly string[]) => ['[', ...values.map(value => `\t${str(value)},`), ']'].join('\n')

/** `app/src/design-tokens.generated.ts`: the presets, native window backgrounds and script motion. */
export function designTokensModule(): string {
	const earlier = Object.entries(PRESET_EARLIER_VALUES)
		.map(([id, tokens]) => {
			const rows = Object.entries(tokens).map(
				([name, values]) => `\t\t${key(name)}: [${(values as readonly string[]).map(str).join(', ')}],`,
			)
			return [`\t${key(id)}: {`, ...rows, '\t},'].join('\n')
		})
		.join('\n')
	return [
		`// Helm design tokens for app TypeScript, ${NOTICE} (docs/design-system.md §2.8).`,
		'// Main and the renderer read token values from here; app code never imports packages/helm-ui.',
		'',
		'/** The Helm preset (§2.1). Key order is the order of the theme file main writes. */',
		`export const HELM_TOKENS: Readonly<Record<string, string>> = ${objectLiteral(HELM_TOKENS, '')}`,
		'',
		'/** The High contrast preset (§2.8, §9 ruling 92). */',
		`export const HIGH_CONTRAST_TOKENS: Readonly<Record<string, string>> = ${objectLiteral(HIGH_CONTRAST_TOKENS, '')}`,
		'',
		'/** Preset id → display name, in picker order. */',
		`export const THEME_PRESET_NAMES: Readonly<Record<string, string>> = ${objectLiteral(
			Object.fromEntries(Object.entries(THEME_PRESETS).map(([id, preset]) => [id, preset.name])),
			'',
		)}`,
		'',
		`export const DEFAULT_THEME_ID = ${literal(DEFAULT_THEME_ID)}`,
		'',
		'/** The names a theme file may set: the preset keys (§2.8). */',
		`export const THEME_TOKEN_NAMES: readonly string[] = ${arrayLiteral(THEME_TOKEN_NAMES)}`,
		'',
		'/** Values a bundled preset carried in an earlier release (§9 ruling 97). */',
		'export const PRESET_EARLIER_VALUES: Readonly<Record<string, Readonly<Record<string, readonly string[]>>>> = {',
		earlier,
		'}',
		'',
		'/** Native window backgrounds before the page paints (§3.30): the Helm pane, and the Review light pane (§3.26). */',
		`export const WINDOW_BACKGROUNDS = ${objectLiteral(
			{ dark: HELM_TOKENS['--pane'], reviewLight: REVIEW_LIGHT_TOKENS['--pane'] },
			'',
		)} as const`,
		'',
		'/** Script-driven motion in milliseconds: the tab drag FLIP and settle (§3.18, §9 ruling 50). */',
		`export const MOTION_MS = ${objectLiteral(SCRIPT_MOTION_MS, '')} as const`,
		'',
		'/** Script-driven easings: the tab drag (§3.18, §9 ruling 50) and the swipe-back settle (§3.10, §9 ruling 35). */',
		`export const EASINGS = ${objectLiteral(SCRIPT_EASINGS, '')} as const`,
		'',
	].join('\n')
}

/** `app/.storybook/backgrounds.generated.ts`: the canvas backgrounds (§7). */
export function storybookBackgroundsModule(): string {
	const rows = STORYBOOK_BACKGROUNDS.map(
		b => `\t${b.id}: { name: ${literal(b.name)}, value: ${literal(HELM_TOKENS[b.token])} },`,
	)
	return [
		`// Storybook canvas backgrounds, ${NOTICE}: the §2.1 ladder, so components sit on the surface they ship on.`,
		'export const BACKGROUNDS = {',
		...rows,
		'} as const',
		'',
	].join('\n')
}

/** Replaces what lies between the markers (each alone on its line) with `body`, keeping the marker lines' indent. */
export function replaceRegion(text: string, file: string, body: readonly string[]): string {
	const begin = text.indexOf(BEGIN)
	const end = text.indexOf(END, begin)
	if (begin < 0 || end < 0) throw new Error(`${file}: tokens:begin / tokens:end markers not found`)
	if (text.indexOf(BEGIN, begin + 1) >= 0) throw new Error(`${file}: more than one tokens region`)
	const lineStart = text.lastIndexOf('\n', begin) + 1
	const indent = text.slice(lineStart, begin)
	return `${text.slice(0, begin)}${BEGIN}\n${body.map(line => `${indent}${line}`).join('\n')}\n${indent}${text.slice(end)}`
}

/** Replaces the one match of `pattern` (whose group 1 is the generated part) with `value`. */
export function replaceOne(text: string, file: string, pattern: RegExp, value: string): string {
	const matches = [...text.matchAll(new RegExp(pattern.source, `${pattern.flags.replace('g', '')}g`))]
	if (matches.length !== 1) throw new Error(`${file}: expected one match of ${pattern}, found ${matches.length}`)
	const match = matches[0] as RegExpMatchArray
	const whole = match[0]
	const group = match[1] ?? ''
	const at = (match.index ?? 0) + whole.indexOf(group)
	return `${text.slice(0, at)}${value}${text.slice(at + group.length)}`
}

const need = (file: string, current: string | null): string => {
	if (current === null) throw new Error(`${file} is missing`)
	return current
}

/** The extension widget's `:host` body. */
function extensionHostLines(): string[] {
	const lines: string[] = []
	for (const entry of EXTENSION_HOST) {
		if ('comment' in entry) lines.push(`/* ${entry.comment} */`)
		else if ('soft' in entry) lines.push(`${entry.name}: color-mix(in srgb, var(${entry.soft}) 15%, transparent);`)
		else lines.push(`${entry.name}: ${rootToken(entry.token)};`)
	}
	return lines
}

export const TARGETS: readonly Target[] = [
	{ file: 'app/src/renderer/tokens.css', render: () => tokensCss() },
	{ file: 'app/src/design-tokens.generated.ts', render: () => designTokensModule() },
	{ file: 'app/.storybook/backgrounds.generated.ts', render: () => storybookBackgroundsModule() },
	{
		file: 'extension/src/widget.styles.ts',
		render: current =>
			replaceRegion(need('extension/src/widget.styles.ts', current), 'widget.styles.ts', extensionHostLines()),
	},
	{
		file: 'extension/src/popup.html',
		render: current =>
			replaceRegion(
				need('extension/src/popup.html', current),
				'popup.html',
				POPUP_ROOT.map(name => `${name}: ${rootToken(name)};`),
			),
	},
	{
		file: 'app/src/renderer/document-review/document-review.css',
		render: current =>
			replaceRegion(
				need('document-review.css', current),
				'document-review.css',
				Object.entries(REVIEW_LIGHT_TOKENS).map(([name, value]) => `${name}: ${value};`),
			),
	},
	{
		file: 'app/assets/remote/manifest.webmanifest',
		render: current => {
			const text = need('manifest.webmanifest', current)
			const pane = HELM_TOKENS['--pane']
			const withBackground = replaceOne(text, 'manifest.webmanifest', /"background_color": "([^"]*)"/, pane)
			return replaceOne(withBackground, 'manifest.webmanifest', /"theme_color": "([^"]*)"/, pane)
		},
	},
	{
		file: 'app/scripts/build-remote.mjs',
		render: current =>
			replaceOne(
				need('build-remote.mjs', current),
				'build-remote.mjs',
				/<meta name="theme-color" content="([^"]*)">/,
				HELM_TOKENS['--pane'],
			),
	},
	{
		file: 'app/assets/remote/remote-sw.js',
		render: current =>
			replaceOne(
				need('remote-sw.js', current),
				'remote-sw.js',
				/<style>:root\{([^}]*)\}/,
				REMOTE_OFFLINE_ROOT.map(name => `${name}:${rootToken(name)}`).join(';'),
			),
	},
	{
		// The `.select` chevron (§3.7): a data URI cannot read a custom property, so it carries --text-2's value.
		file: 'app/src/renderer/sidebar/sidebar.css',
		render: current =>
			replaceOne(
				need('sidebar.css', current),
				'sidebar.css',
				/stroke='(%23[0-9a-fA-F]{3,8})' stroke-width/,
				encodeURIComponent(HELM_TOKENS['--text-2']),
			),
	},
]
